[{"location":"PlummerLens/#LensFactory.Lenses.init_PlummerLens","page":"Plummer Lens","title":"LensFactory.Lenses.init_PlummerLens","text":"init_PlummerLens(D_d::RV=NaN, x_c::RV=0.0, y_c::RV=0.0, mass::RV=NaN, x_s::RV=NaN)\n\nInitialize a Plummer lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"PlummerLens/#LensFactory.Lenses.PlummerLens.potential!","page":"Plummer Lens","title":"LensFactory.Lenses.PlummerLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PlummerLens/#LensFactory.Lenses.PlummerLens.deflection!","page":"Plummer Lens","title":"LensFactory.Lenses.PlummerLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PlummerLens/#LensFactory.Lenses.PlummerLens.jacobian!","page":"Plummer Lens","title":"LensFactory.Lenses.PlummerLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PlummerLens/#LensFactory.Lenses.PlummerLens.einstein_angle","page":"Plummer Lens","title":"LensFactory.Lenses.PlummerLens.einstein_angle","text":"einstein_angle(;D_d::Float64=NaN, D_ds::Float64=NaN, D_s::Float64=NaN, mass::Float64=NaN, x_s::Float64=NaN)\n\n\n\n\n\n","category":"function"},{"location":"HernquistLens/#LensFactory.Lenses.init_HernquistLens","page":"Hernquist Lens","title":"LensFactory.Lenses.init_HernquistLens","text":"init_HernquistLens(D_d::RV=NaN, x_c::RV=0.0, y_c::RV=0.0, mass::RV=NaN, x_e::RV=NaN)\n\nInitialize a Hernquist lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"HernquistLens/#LensFactory.Lenses.HernquistLens.potential!","page":"Hernquist Lens","title":"LensFactory.Lenses.HernquistLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"HernquistLens/#LensFactory.Lenses.HernquistLens.deflection!","page":"Hernquist Lens","title":"LensFactory.Lenses.HernquistLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"HernquistLens/#LensFactory.Lenses.HernquistLens.jacobian!","page":"Hernquist Lens","title":"LensFactory.Lenses.HernquistLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"SersicLens/#LensFactory.Lenses.init_SersicLens","page":"Sersic Lens","title":"LensFactory.Lenses.init_SersicLens","text":"init_SersicLens(D_d::RV=NaN, x_c::RV=0.0, y_c::RV=0.0, mass::RV=NaN, x_e::RV=NaN, n::RV=4)\n\nInitialize a Sersic lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"SersicLens/#LensFactory.Lenses.SersicLens.potential!","page":"Sersic Lens","title":"LensFactory.Lenses.SersicLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV, n::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV, n::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"SersicLens/#LensFactory.Lenses.SersicLens.deflection!","page":"Sersic Lens","title":"LensFactory.Lenses.SersicLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV, n::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV, n::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"SersicLens/#LensFactory.Lenses.SersicLens.jacobian!","page":"Sersic Lens","title":"LensFactory.Lenses.SersicLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV, n::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θe::RV, n::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"SersicLens/#LensFactory.Lenses.SersicLens.scale_to_halflight","page":"Sersic Lens","title":"LensFactory.Lenses.SersicLens.scale_to_halflight","text":"scale_to_halflight(;n::RV=NaN, x_s::RV=NaN)\n\n\n\n\n\n","category":"function"},{"location":"SISLens/#LensFactory.Lenses.init_SISLens","page":"SIS Lens","title":"LensFactory.Lenses.init_SISLens","text":"init_SISLens(x_c::RV=0.0, y_c::RV=0.0, v_d::RV=NaN)\n\nInitialize a Singular Isothermal Sphere (SIS) lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"SISLens/#LensFactory.Lenses.SISLens.potential!","page":"SIS Lens","title":"LensFactory.Lenses.SISLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"SISLens/#LensFactory.Lenses.SISLens.deflection!","page":"SIS Lens","title":"LensFactory.Lenses.SISLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"SISLens/#LensFactory.Lenses.SISLens.jacobian!","page":"SIS Lens","title":"LensFactory.Lenses.SISLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"SISLens/#LensFactory.Lenses.SISLens.einstein_angle","page":"SIS Lens","title":"LensFactory.Lenses.SISLens.einstein_angle","text":"einstein_angle(;D_ds::Float64=NaN, D_s::Float64=NaN, v_d::RV=NaN)\n\n\n\n\n\n","category":"function"},{"location":"GaussianLens/#LensFactory.Lenses.init_GaussianLens","page":"Gaussian Lens","title":"LensFactory.Lenses.init_GaussianLens","text":"init_GaussianLens(D_d::RV=NaN, x_c::RV=0.0, y_c::RV=0.0, mass::RV=NaN, x_s::RV=NaN)\n\nInitialize a Gaussian lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"GaussianLens/#LensFactory.Lenses.GaussianLens.potential!","page":"Gaussian Lens","title":"LensFactory.Lenses.GaussianLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"GaussianLens/#LensFactory.Lenses.GaussianLens.deflection!","page":"Gaussian Lens","title":"LensFactory.Lenses.GaussianLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"GaussianLens/#LensFactory.Lenses.GaussianLens.jacobian!","page":"Gaussian Lens","title":"LensFactory.Lenses.GaussianLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology","page":"Cosmology","title":"LensFactory.Cosmology","text":"Cosmology\n\n\n\n\n\n","category":"module"},{"location":"Cosmology/#Initialization","page":"Cosmology","title":"Initialization","text":"","category":"section"},{"location":"Cosmology/#LensFactory.Cosmology.init_cosmology","page":"Cosmology","title":"LensFactory.Cosmology.init_cosmology","text":"init_cosmology(H0::RV=70.0, w::RV=-1.0, Omega_m0::RV=0.3, Omega_r0::RV=0.0, Omega_w0::RV=0.7)\n\nAn Abstract type to initialize a given cosmology.\n\n\n\n\n\n","category":"type"},{"location":"Cosmology/#Basics","page":"Cosmology","title":"Basics","text":"","category":"section"},{"location":"Cosmology/#LensFactory.Cosmology.scale_factor","page":"Cosmology","title":"LensFactory.Cosmology.scale_factor","text":"scale_factor(z::RV)\n\nCalculates the scale factor (a) at redshift z. The formula is,\n\na = frac11+z\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.Ez","page":"Cosmology","title":"LensFactory.Cosmology.Ez","text":"Ez(z::RV)\n\nCalculates the dimensionless Hubble parameter (E) at redshift, z.  The formula is,\n\nE(z) = sqrt Ω_m0 (1+z)^2 + Ω_r0 (1+z)^4 + Ω_k0 (1+z)^2 + Ω_w0 (1+z)^3(1+w) \n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.hubble_parameter","page":"Cosmology","title":"LensFactory.Cosmology.hubble_parameter","text":"hubble_parameter(cosmology::AbstractCosmology, z::RV)\n\nCalculates the Hubble parameter (H) at redshift z in rm mathbfkmsMpc.  The formula is,\n\nH(z) = H_0  E(z)\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#Time","page":"Cosmology","title":"Time","text":"","category":"section"},{"location":"Cosmology/#LensFactory.Cosmology.hubble_time","page":"Cosmology","title":"LensFactory.Cosmology.hubble_time","text":"hubble_time(H0::RV)\n\nCalculates the Hubble time (t_H) in rm mathbfGyr. The formula is,\n\nt_H = frac1H_0\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.age","page":"Cosmology","title":"LensFactory.Cosmology.age","text":"age(cosmology::AbstractCosmology, z::RV)\n\nCalculates the age (t_rm age) of the Universe at redshift z in rm mathbfGyr. The formula is,\n\nt_rm age(z) = int_z^infty frac1(1+z)H(z) dz \n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.lookback_time","page":"Cosmology","title":"LensFactory.Cosmology.lookback_time","text":"lookback_time(cosmology::AbstractCosmology, z::RV)\n\nCalculates lookbak time (t_L) to a given redshift z in rm mathbfGyr. The formula is,\n\nt_L(z) = int_0^z frac1(1+z)H(z) dz \n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#Density-parameters","page":"Cosmology","title":"Density parameters","text":"","category":"section"},{"location":"Cosmology/#LensFactory.Cosmology.rho_cz","page":"Cosmology","title":"LensFactory.Cosmology.rho_cz","text":"rho_cz(cosmology::AbstractCosmology, z::RV)\n\nCalculates the critical density (rho_c) of the Universe at redshift z in rm mathbfkgm^3. The formula is,\n\nrho_c(z) = frac3 H^2(z)8 π rm G \n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.Omega_mz","page":"Cosmology","title":"LensFactory.Cosmology.Omega_mz","text":"Omega_mz(cosmology::AbstractCosmology, z::RV)\n\nCalculates the matter density parameter (Omega_m) at redshift z. The formula is,\n\nΩ_m(z) = Ω_m(0)  (1+z)^3 left( fracH0H(z) right)^2\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.Omega_rz","page":"Cosmology","title":"LensFactory.Cosmology.Omega_rz","text":"Omega_rz(cosmology::AbstractCosmology, z::RV)\n\nCalculates the matter density parameter (Omega_r) at redshift z. The formula is,\n\nΩ_r(z) = Ω_r(0)  (1+z)^4 left( fracH_0H(z) right)^2\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.Omega_wz","page":"Cosmology","title":"LensFactory.Cosmology.Omega_wz","text":"Omega_wz(cosmology::AbstractCosmology, z::RV)\n\nCalculates the dark energy density parameter (Omega_w) at redshift z. The formula is,\n\nΩ_w(z) = Ω_w0 (1+z)^3(1+w) left( fracH_0H(z) right)^2\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.Omega_kz","page":"Cosmology","title":"LensFactory.Cosmology.Omega_kz","text":"Omega_kz(cosmology::AbstractCosmology, z::RV)\n\nCalculates the curvature density parameter (Omega_k) at redshift z. The formula is,\n\nΩ_k(z) = Ω_k0 (1+z)^2 left( fracH_0H(z) right)^2\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#Distances","page":"Cosmology","title":"Distances","text":"","category":"section"},{"location":"Cosmology/#LensFactory.Cosmology.hubble_distance","page":"Cosmology","title":"LensFactory.Cosmology.hubble_distance","text":"hubble_distance(H0::RV)\n\nCalculates HUbble distance (i.e., size of the observable Universe) (D_H) in rm mathbfmeters.  The formula is\n\nD_H = fracrm crm H_0 \n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.comoving_distance_radial","page":"Cosmology","title":"LensFactory.Cosmology.comoving_distance_radial","text":"comoving_distance_radial(cosmo::AbstractCosmology, z1::RV, z2::RV)\n\nCalculates the comoving radial distance (D_C) between z_1 and z_2 in rm mathbfmeters. The formula is,\n\nD_C = D_H int_z_1^z_2 fracdzE(z)\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.comoving_distance_transverse","page":"Cosmology","title":"LensFactory.Cosmology.comoving_distance_transverse","text":"comoving_distance_transverse(cosmo::AbstractCosmology, z1::RV, z2::RV)\n\nCalculates the comoving radial distance (D_M) between, z_1 and z_2 in rm mathbfmeters. The formula is,\n\nD_M = begincases \nD_H frac1sqrtOmega_k   sinh left sqrtOmega_k    D_C  D_H right  textif  Omega_k  0 \nD_C                                                                                           textif  Omega_k = 0 \nD_H frac1sqrtOmega_k  sin left sqrtOmega_k  D_C  D_H right  textif  Omega_k  0 \nendcases\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.luminosity_distance","page":"Cosmology","title":"LensFactory.Cosmology.luminosity_distance","text":"luminosity_distance(cosmology::AbstractCosmology, z::RV)\n\nCalculates the luminosity distance (D_L) to redshift z in rm mathbfmeters.  The formula is,\n\nD_L(z) = (1+z) D_M(z)\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.angular_diameter_distance","page":"Cosmology","title":"LensFactory.Cosmology.angular_diameter_distance","text":"angular_diameter_distance(cosmology::AbstractCosmology, z1::RV, z2::RV)\n\nCalculates the angular diameter distance (D_A) between redshifts z_1 and z_2 in rm mathbfmeters.  The formula is,\n\nD_A(z_1 z_2) = fracD_M(z_1 z_2)1+z_2\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.distance_modulus","page":"Cosmology","title":"LensFactory.Cosmology.distance_modulus","text":"distance_modulus(cosmo::AbstractCosmology, z::RV)\n\nCalculates the distance modulus (mu) to a given redshift z.  The formula is,\n\nmu = 5 logleft( fracD_Lrm pc right) - 5\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.angular_scale","page":"Cosmology","title":"LensFactory.Cosmology.angular_scale","text":"angular_scale(cosmo::AbstractCosmology, z::RV)\n\nCalculates the angular size in rm mathbfKpc for 1 on sky at redhsift, z.  The formula is\n\nd = 1 times left( fracD_Armkpc right)\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#Volumes","page":"Cosmology","title":"Volumes","text":"","category":"section"},{"location":"Cosmology/#LensFactory.Cosmology.comoving_volume_element","page":"Cosmology","title":"LensFactory.Cosmology.comoving_volume_element","text":"comoving_volume_element(cosmology::AbstractCosmology, z::RV)\n\nCalculates the comving volume element (dV_C) at redshift z in rm mathbfGpc^3. The formula is\n\ndV_C = D_H fracD_M^2(z)E(z)\n\n\n\n\n\n","category":"function"},{"location":"Cosmology/#LensFactory.Cosmology.comoving_volume","page":"Cosmology","title":"LensFactory.Cosmology.comoving_volume","text":"comoving_volume(cosmology::AbstractCosmology, z::RV)\n\nCalculates the total comving volume up to redshift z in rm mathbfGpc^3. The formula is,\n\nV_C = begincases \nfrac4π2 fracD_H^3Ω_k \n   left fracD_MD_H sqrt1+Ω_k left(fracD_MD_Hright)^2 \n   - frac1sqrtΩ_k rm arcsinhleft( sqrtΩ_k fracD_MD_H  right) right  textif  Ω_k  0 \nfrac4π3 D_M^3                                                   textif  Ω_k = 0 \nfrac4π2 fracD_H^3Ω_k left fracD_MD_H sqrt1+Ω_k left(fracD_MD_Hright)^2 \n      - frac1sqrtΩ_k arcsinleft( sqrtΩ_k fracD_MD_H  right) right  textif  Ω_k  0 \nendcases\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses","page":"Basics","title":"LensFactory.Lenses","text":"Lenses\n\n\n\n\n\n","category":"module"},{"location":"Lenses/#LensFactory.Lenses.get_meshgrid","page":"Basics","title":"LensFactory.Lenses.get_meshgrid","text":"get_meshgrid(θx::RV, θy::RV, dθ::RV)\n\nGenerate a meshgrid of coordinates on which various quantities can be evaluated. At present, this function only generates square pixels. In future if the need arises, it can be extended  to generate rectangular pixels as well.\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_critical_density","page":"Basics","title":"LensFactory.Lenses.get_critical_density","text":"get_critical_density(; Dd::Float64=NaN, Dds::Float64=NaN, Ds::Float64=NaN, adis::Float64=NaN; unit::Symbol=:kg_m2)\n\nCalculate the critical surface density,\n\nΣ_rm cr = fracc^24 π rm G fracD_sD_d D_ds\n\ngiven the angular diameter distances. The result can be returned in different units,\n\n:kg_m2 Rightarrowrm kgm^2, \n:msun_pc2 Rightarrowrm M_pc^2, \n:msun_arcsec2 Rightarrowrm M_arcsec^2.\n\nnote: Note\nAs we can see from formula, to estimate Σ_rm cr, we need either (D_dD_dsD_s) or (D_da_rm dis). The latter takes precedent during Σ_rm cr estimation.\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_potential","page":"Basics","title":"LensFactory.Lenses.get_potential","text":"get_potential(lens::AbstractLens, θx::ROA, θy::ROA)\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_deflection","page":"Basics","title":"LensFactory.Lenses.get_deflection","text":"get_deflection(lens::AbstractLens, θx::ROA, θy::ROA)\n\nCalculates the deflection angles (i.e., the gradient of the potential) for a given lens model.  Returns a tuple of deflection components, i.e., (ψ_x ψ_y).\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_jacobian","page":"Basics","title":"LensFactory.Lenses.get_jacobian","text":"get_jacobian(lens::AbstractLens, θx::ROA, θy::ROA)\n\nCalculates the jacobian (i.e., deformation tensor) of the lens mapping for a given lens model. The jacobian is a 2times2 matrix composed of the second derivatives of the potential,  which is given as,\n\nmathcalA =\nbeginpmatrix\nψ_xx  ψ_xy \nψ_xy  ψ_yy\nendpmatrix\n\nSince the jacobian is symmetric (for single lens plane), only three components are returned, i.e., (ψ_xx ψ_yy ψ_xy).\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_time_delay","page":"Basics","title":"LensFactory.Lenses.get_time_delay","text":"get_time_delay(lens::AbstractLens, θx::ROA, θy::ROA)\n\nCalculates the time delay for a given lens model. The corresponding expression is given as,\n\nt_d(pmbθ pmbβ) = frac1+z_lrm c fracD_d D_sD_ds theta_0^2\n   left frac(pmbθ - pmbβ)^22 - fracD_dsD_s psi(pmbθ) right\n\nwhere theta_0 is normalizing angular unit.\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_magnification_image","page":"Basics","title":"LensFactory.Lenses.get_magnification_image","text":"get_magnification(lens::AbstractLens, θx::ROA, θy::ROA)\n\nCalculates the magnification for a given lens model. The corresponding expression is given as,\n\nmu = frac1det mathcalA = frac1(1 - κ)^2 - γ^2\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_image","page":"Basics","title":"LensFactory.Lenses.get_image","text":"get_image(lens::AbstractLens, θx::ROA, θy::ROA, adis::Float64, β::NTuple{2, RV})\nget_image(lens::AbstractLens, θx::ROA, θy::ROA, adis::Float64, β::Matrix{<:RV})\n\nCalculates the image position for a given lens model by solving the lens equation,\n\npmbβ = pmbθ - fracD_dsD_s psi(pmbθ)\n\nIn case of a point source, given by pmbβ = (β_1β_2), the current implementation finds  the intersection points of contours corresponding to pmbβ - pmbθ + a_rm dis psi(pmbθ) = 0. On the other hand, for an extended source, the function does inverse ray shooting to construct the image plane.\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_critical_curve","page":"Basics","title":"LensFactory.Lenses.get_critical_curve","text":"get_critical_curve(lens::AbstractLens, θx::T, θy::T, adis::Float64) where T <: Matrix{<:RV}\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_caustic","page":"Basics","title":"LensFactory.Lenses.get_caustic","text":"get_caustic(lens::AbstractLens, θx::T, θy::T, adis::Float64) where T <: Matrix{<:RV}\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_critical_area","page":"Basics","title":"LensFactory.Lenses.get_critical_area","text":"get_critical_area(lens::AbstractLens, θx::T, θy::T, adis::Float64) where T <: Matrix{<:RV}\n\n\n\n\n\n","category":"function"},{"location":"Lenses/#LensFactory.Lenses.get_einstein_angle","page":"Basics","title":"LensFactory.Lenses.get_einstein_angle","text":"get_einstein_angle(lens::AbstractLens, θx::T, θy::T, adis::Float64) where T <: Matrix{<:RV}\n\n\n\n\n\n","category":"function"},{"location":"PointLens/","page":"Point Lens","title":"Point Lens","text":"Arguably the simplest lens model is a point mass (Schwarzschild) lens, which is described by two parameters, namely, mass (M) and source position (y). The (psi hatalpha kappa) for a point mass lens are given as,","category":"page"},{"location":"PointLens/","page":"Point Lens","title":"Point Lens","text":"beginalign*\npsi(theta) = theta_E^2 ln(theta) \nhatalpha(theta) = fractheta_E^2theta \nkappa(theta) = fracMSigma_rm cr delta(theta)\nendalign*","category":"page"},{"location":"PointLens/","page":"Point Lens","title":"Point Lens","text":"where theta_E is the Einstein angle, which is given as,","category":"page"},{"location":"PointLens/","page":"Point Lens","title":"Point Lens","text":"beginequation*\ntheta_E = sqrtfrac4rm GMrm c^2 fracD_dsD_d D_s\nendequation*","category":"page"},{"location":"PointLens/#LensFactory.Lenses.init_PointLens","page":"Point Lens","title":"LensFactory.Lenses.init_PointLens","text":"init_PointLens(D_d::RV=NaN, x_c::RV=0.0, y_c::RV=0.0, mass::RV=NaN)\n\nInitialize a point lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"PointLens/#LensFactory.Lenses.PointLens.potential!","page":"Point Lens","title":"LensFactory.Lenses.PointLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PointLens/#LensFactory.Lenses.PointLens.deflection!","page":"Point Lens","title":"LensFactory.Lenses.PointLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PointLens/#LensFactory.Lenses.PointLens.jacobian!","page":"Point Lens","title":"LensFactory.Lenses.PointLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, mass::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PointLens/#LensFactory.Lenses.PointLens.einstein_angle","page":"Point Lens","title":"LensFactory.Lenses.PointLens.einstein_angle","text":"einstein_angle(;D_d::Float64=NaN, D_ds::Float64=NaN, D_s::Float64=NaN, mass::Float64=NaN)\n\n\n\n\n\n","category":"function"},{"location":"History/","page":"History","title":"History","text":"Date Version Comments\n03/09/2025 0.0.1 First release.\n08/09/2025 0.0.2 Breaking. Updated the input arguments. Added support for multi-plane lensing and new lens models.","category":"page"},{"location":"MultiPlane/#LensFactory.MultiPlane","page":"Multi-plane lensing","title":"LensFactory.MultiPlane","text":"MultiPlane\n\n\n\n\n\n","category":"module"},{"location":"PlotExt/","page":"Plot Extension","title":"Plot Extension","text":"This part contains plotting support for the LensFactory.jl package. ","category":"page"},{"location":"PlotExt/#LensFactory.Lenses.plot_image_plane","page":"Plot Extension","title":"LensFactory.Lenses.plot_image_plane","text":"LensFactory.Lenses.plot_image_plane(lens::Lenses.AbstractLens, θx::ROA, θy::ROA, adis::RV)\n\nAdditional keyword arguments and their default values\n\ntwo_panel::Bool = false – Whether to create a two-panel plot with source plane on the left and image plane on the right\nplot_caustic::Bool = true\ncaustic_kws::NamedTuple = (color_tan = :green, color_rad = :green, linewidth = 2)\nplot_critical::Bool =true\ncritical_kws::NamedTuple = (color_tan = :red, color_rad = :red, linewidth = 2)\nsource::Union{Nothing, NTuple{2, RV}, Matrix{<:RV}} = nothing\nsource_kws::NamedTuple = (color=:red, markersize=10, marker=:star5, heatmap=cgrad([:white, :blue]))\nimage_kws::NamedTuple = (color=:blue, markersize=10, marker=:star5, heatmap=cgrad([:white, :red]))\nsave_plot::Bool = false\nplot_name::String = \"image_plane.png\"\nresolution::Int = 2\n\n\n\n\n\n","category":"function"},{"location":"PlotExt/#LensFactory.Lenses.plot_surface_density","page":"Plot Extension","title":"LensFactory.Lenses.plot_surface_density","text":"LensFactory.Lenses.plot_surface_density(lens::Lenses.AbstractLens, θx::ROA, θy::ROA, adis::Float64; D_d::Float6=NaN)\n\nAdditional keyword arguments and their default values\n\nunit::Symbol = :kg_m2 – Unit for surface density. Options are :convergence, :kgm2, :msunpc2, :msun_arcsec2\nfigure_size::NTuple{2, RV} = (500, 400)\nheatmap_kws::NamedTuple = (colormap=:cubehelix, colorrange=(0, 6))\nplot_contour::Bool = false\ncontour_kws::NamedTuple = (levels=0.5:0.2:1.5, labels=false)\nsave_plot::Bool = false\nplot_name::String = \"surface_density.png\"\nresolution::Int = 2\n\n\n\n\n\n","category":"function"},{"location":"PlotExt/#LensFactory.Lenses.plot_magnification_map","page":"Plot Extension","title":"LensFactory.Lenses.plot_magnification_map","text":"LensFactory.Lenses.plot_magnification_map(lens::Lenses.AbstractLens, θx::ROA, θy::ROA, adis::Float64)\n\nAdditional keyword arguments and their default values\n\nplane::Symbol = :image – Whether to plot |μ| map in :image or :source plane\nrays_per_pixel::Int64 = 1 – Only relevant if plane = :source\nfigure_size::NTuple{2, RV} = (500, 400)\nheatmap_kws::NamedTuple = (colormap=:binary, colorrange=(1, 100))\nsave_plot::Bool = false\nplot_name::String = \"magnification_map.png\"\nresolution::Int = 2\n\n\n\n\n\n","category":"function"},{"location":"PlotExt/#LensFactory.Lenses.plot_magnification_profile","page":"Plot Extension","title":"LensFactory.Lenses.plot_magnification_profile","text":"LensFactory.Lenses.plot_magnification_profile(lens::Lenses.AbstractLens, θx::ROA, θy::ROA, adis::Float64)\n\nAdditional keyword arguments and their default values\n\nplane::Symbol = :image – Whether to plot |μ| map in :image or :source plane\nrays_per_pixel::Int64 = 1 – Only relevant if plane = :source\nmu_range::StepRange{<:RV, <:RV} = 1:5:500\nunit::Float64 = ANGLE_ARCMIN^2\nfigure_size::NTuple{2, RV} = (500, 400)\nplot_kws::NamedTuple = (color=:black, linewidth=2, linestyle=:solid)\nsave_plot::Bool = false\nplot_name::String = \"magnification_profile.png\"\nresolution::Int = 2\n\n\n\n\n\n","category":"function"},{"location":"PlotExt/#LensFactory.MultiPlane.plot_image_plane","page":"Plot Extension","title":"LensFactory.MultiPlane.plot_image_plane","text":"LensFactory.MultiPlane.plot_image_plane(cosmology::Cosmology.AbstractCosmology, lens::Lenses.AbstractLens, θx::ROA, θy::ROA, zs::RV)\n\nAdditional keyword arguments and their default values\n\ntwo_panel::Bool = false – Whether to create a two-panel plot with source plane on the left and image plane on the right\nplot_caustic::Bool = true\ncaustic_kws::NamedTuple = (color = :green, linewidth = 2)\nplot_critical::Bool =true\ncritical_kws::NamedTuple = (color = :red, linewidth = 2)\nsource::Union{Nothing, NTuple{2, RV}, Matrix{<:RV}} = nothing\nsource_kws::NamedTuple = (color=:red, markersize=10, marker=:star5, heatmap=cgrad([:white, :blue]))\nimage_kws::NamedTuple = (color=:blue, markersize=10, marker=:star5, heatmap=cgrad([:white, :red]))\nsave_plot::Bool = false\nplot_name::String = \"image_plane.png\"\nresolution::Int = 2\n\n\n\n\n\n","category":"function"},{"location":"NFWLens/#LensFactory.Lenses.init_NFWLens","page":"NFW Lens","title":"LensFactory.Lenses.init_NFWLens","text":"init_NFWLens(D_d::RV=NaN, x_c::RV=0.0, y_c::RV=0.0, x_s::RV=NaN, c::RV=NaN, rho_s::RV=NaN, mass::RV=NaN)\n\nInitialize a Navarro-Frenk-White (NFW) lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"NFWLens/#LensFactory.Lenses.NFWLens.potential!","page":"NFW Lens","title":"LensFactory.Lenses.NFWLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, ρs:: RV, θs::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, ρs:: RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NFWLens/#LensFactory.Lenses.NFWLens.deflection!","page":"NFW Lens","title":"LensFactory.Lenses.NFWLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, ρs:: RV, θs::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, ρs:: RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NFWLens/#LensFactory.Lenses.NFWLens.jacobian!","page":"NFW Lens","title":"LensFactory.Lenses.NFWLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, ρs:: RV, θs::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, D_d::RV, θxc::RV, θyc::RV, ρs:: RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PIEPLens/#LensFactory.Lenses.init_PIEPLens","page":"PIEP Lens","title":"LensFactory.Lenses.init_PIEPLens","text":"init_PIEPLens(x_c::RV=0.0, y_c::RV=0.0, v_d::RV=NaN, x_s::RV=NaN, eps::RV=NaN, pa::RV=NaN)\n\nInitialize pseudo isothermal elliptical potential (PIEP) lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"PIEPLens/#LensFactory.Lenses.PIEPLens.potential!","page":"PIEP Lens","title":"LensFactory.Lenses.PIEPLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PIEPLens/#LensFactory.Lenses.PIEPLens.deflection!","page":"PIEP Lens","title":"LensFactory.Lenses.PIEPLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PIEPLens/#LensFactory.Lenses.PIEPLens.jacobian!","page":"PIEP Lens","title":"LensFactory.Lenses.PIEPLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NSISPLens/#LensFactory.Lenses.init_NSISPLens","page":"NSISP Lens","title":"LensFactory.Lenses.init_NSISPLens","text":"init_NSISPLens(x_c::RV=0.0, y_c::RV=0.0, v_d::RV=NaN, x_s::RV=NaN)\n\nInitialize a Non-Singular Isothermal Sphere potential (NSISP) lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"NSISPLens/#LensFactory.Lenses.NSISPLens.potential!","page":"NSISP Lens","title":"LensFactory.Lenses.NSISPLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NSISPLens/#LensFactory.Lenses.NSISPLens.deflection!","page":"NSISP Lens","title":"LensFactory.Lenses.NSISPLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NSISPLens/#LensFactory.Lenses.NSISPLens.jacobian!","page":"NSISP Lens","title":"LensFactory.Lenses.NSISPLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NSISPLens/#LensFactory.Lenses.NSISPLens.einstein_angle","page":"NSISP Lens","title":"LensFactory.Lenses.NSISPLens.einstein_angle","text":"einstein_angle(;D_ds::Float64=NaN, D_s::Float64=NaN, v_d::RV=NaN, x_s::Float64=NaN)\n\n\n\n\n\n","category":"function"},{"location":"Sources/#LensFactory.Sources","page":"Sources","title":"LensFactory.Sources","text":"Sources\n\n\n\n\n\n","category":"module"},{"location":"Sources/#LensFactory.Sources.disk","page":"Sources","title":"LensFactory.Sources.disk","text":"disk(θx::Matrix{<:RV}, θy::Matrix{<:RV}, θr::RV, β::NTuple{2, RV}; A::RV=1.0) --> Matrix{<:RV}\n\nCreates a disk source profile of radius θ_r on a grid defined by θ_x θ_y.  The center of the disk is at pmbβ = (β_x β_y). By default, the source profile is constant and every pixel has a value of 1.0 and we can scale it using the amplitude A. The corresponding formula is:\n\nS(θ_x θ_y) =\nbegincases\n   A  textif  (θ_x - β_x)^2 + (θ_y - β_y)^2  θ_r^2 \n   0  textotherwise\nendcases\n\n\n\n\n\n","category":"function"},{"location":"Sources/#LensFactory.Sources.gaussian","page":"Sources","title":"LensFactory.Sources.gaussian","text":"gaussian(θx::Matrix{<:RV}, θy::Matrix{<:RV}, σx::RV, σy::RV, β::NTuple{2, RV}; A::RV=1.0) --> Matrix{<:RV}\n\nCreates a Gaussian source profile on a grid defined by θ_x θ_y. Standard deviations along  (x y) axis are given by (σ_x σ_y). The center of the Gaussian is at pmbβ = (β_x β_y).  The overall normalization is determined by A. The corresponding formula is:\n\nS(θ_x θ_y) = fracA2 π σ_x σ_y expleft-frac12 left(frac(θ_x - β_x)^2σ_x^2 + frac(θ_y - β_y)^2σ_y^2right)right\n\n\n\n\n\n","category":"function"},{"location":"Sources/#LensFactory.Sources.sersic","page":"Sources","title":"LensFactory.Sources.sersic","text":"sersic(θx::Matrix{<:RV}, θy::Matrix{<:RV}, n::RV, θe::RV, β::NTuple{2, RV}; A::RV=1.0) --> Matrix{<:RV}\n\nCreates a Sersic source profile on a grid defined by θ_x θ_y. The Sersic index is given by n and the effective radius is given by θ_e. The center of the Sersic profile is at pmbβ = (β_x β_y). The overall normalization is determined by A. The corresponding formula is:\n\nS(θ_x θ_y) = fracA b_n^2nπ θ_e^2  Γ(2n+1) \nexpleft-b_n left(fracsqrt(θ_x - β_x)^2 + (θ_y - β_y)^2θ_eright)^1nright\n\nwhere,\n\nb_n = \nbegincases\n001945 - 08902n + 1095n^2 - 1967n^3 + 1343n^4  006  n  036 \n2n - frac13 + frac4405n + frac4625515n^2 + frac1311148175n^3 - frac219469730690717750n^4  n  036\nendcases\n\n\n\n\n\n","category":"function"},{"location":"Constants/#LensFactory.Constants","page":"Constants","title":"LensFactory.Constants","text":"Constants\n\n\n\n\n\n","category":"module"},{"location":"Constants/#Natural-constants","page":"Constants","title":"Natural constants","text":"","category":"section"},{"location":"Constants/","page":"Constants","title":"Constants","text":"CONST_C = 299792458.0                        # Speed of light (in meters/s)\nCONST_G = 6.6743E-11                         # Gravitational constant (in m^3 kg/s^2)","category":"page"},{"location":"Constants/#Solar-constants","page":"Constants","title":"Solar constants","text":"","category":"section"},{"location":"Constants/","page":"Constants","title":"Constants","text":"MASS_SUN = 1.988409870698051E+30             # Solar mass (in kg)\nRADIUS_SUN = 695700000.0                     # Solar radius (in meters)\nLUMINOSITY_SUN = 3.828E26                    # Solar luminosity (Watts = Joule/s)","category":"page"},{"location":"Constants/#Distance-units","page":"Constants","title":"Distance units","text":"","category":"section"},{"location":"Constants/","page":"Constants","title":"Constants","text":"DIST_AU  = 1.495978707000000E+11             # One Astronomical Unit (in meters)\nDIST_PC  = 3.085677581491367E+16             # One parsec (in meters)\nDIST_KPC = 3.085677581491367E+19             # One kiloparsec (in meters)\nDIST_MPC = 3.085677581491367E+22             # One Megaparsec (in meters)\nDIST_GPC = 3.085677581491367E+25             # One Gigaparsec (in meters)","category":"page"},{"location":"Constants/#Angular-units","page":"Constants","title":"Angular units","text":"","category":"section"},{"location":"Constants/","page":"Constants","title":"Constants","text":"ANGLE_MICROARCSEC = 4.848136811095361E-12    # One micro-arcsecond (in radians)\nANGLE_MILLIARCSEC = 4.848136811095361E-09    # One milli-arcsecond (in radians)\nANGLE_ARCSEC = 4.848136811095361E-06         # One arcsecond (in radians)\nANGLE_ARCMIN = 0.0002908882086657216         # One arcminute (in radians)\nANGLE_DEGREE = 0.017453292519943295          # One degree (in radians)","category":"page"},{"location":"Constants/#Temporal-units","page":"Constants","title":"Temporal units","text":"","category":"section"},{"location":"Constants/","page":"Constants","title":"Constants","text":"YEAR2SECOND = 31557600.0                     # Seconds in a year\nYEAR2HOUR   = 8766.0                         # Hours in a year\nYEAR2DAY    = 365.25                         # Days in a year\nDAY2HOUR    = 24.0                           # Hours in a day\nDAY2SECOND  = 86400.0                        # Seconds in a day","category":"page"},{"location":"SIELens/#LensFactory.Lenses.init_SIELens","page":"SIE Lens","title":"LensFactory.Lenses.init_SIELens","text":"init_SIELens(x_c::RV=0.0, y_c::RV=0.0, v_d::RV=NaN, x_s::RV=NaN, eps::RV=NaN, pa::RV=NaN)\n\nInitialize singular isothermal ellipsoid (SIE) lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"SIELens/#LensFactory.Lenses.SIELens.potential!","page":"SIE Lens","title":"LensFactory.Lenses.SIELens.potential!","text":"potential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"SIELens/#LensFactory.Lenses.SIELens.deflection!","page":"SIE Lens","title":"LensFactory.Lenses.SIELens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"SIELens/#LensFactory.Lenses.SIELens.jacobian!","page":"SIE Lens","title":"LensFactory.Lenses.SIELens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, ϵ::RV, pa::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NSISMDLens/#LensFactory.Lenses.init_NSISMDLens","page":"NSISMD Lens","title":"LensFactory.Lenses.init_NSISMDLens","text":"init_NSISMDLens(x_c::RV=0.0, y_c::RV=0.0, v_d::RV=NaN, x_s::RV=NaN)\n\nInitialize a Non-Singular Isothermal Sphere mass distribution (NSISMD) lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"NSISMDLens/#LensFactory.Lenses.NSISMDLens.potential!","page":"NSISMD Lens","title":"LensFactory.Lenses.NSISMDLens.potential!","text":"potential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NSISMDLens/#LensFactory.Lenses.NSISMDLens.deflection!","page":"NSISMD Lens","title":"LensFactory.Lenses.NSISMDLens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NSISMDLens/#LensFactory.Lenses.NSISMDLens.jacobian!","page":"NSISMD Lens","title":"LensFactory.Lenses.NSISMDLens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"NSISMDLens/#LensFactory.Lenses.NSISMDLens.einstein_angle","page":"NSISMD Lens","title":"LensFactory.Lenses.NSISMDLens.einstein_angle","text":"einstein_angle(;D_ds::Float64=NaN, D_s::Float64=NaN, v_d::RV=NaN, x_s::Float64=NaN)\n\n\n\n\n\n","category":"function"},{"location":"PJELens/#LensFactory.Lenses.init_PJELens","page":"PJE Lens","title":"LensFactory.Lenses.init_PJELens","text":"init_PJEMDLens(x_c::RV=0.0, y_c::RV=0.0, v_d::RV=NaN, x_s::RV=NaN, x_t::RV=NaN, eps::RV=NaN, pa::RV=NaN)\n\nInitialize Pseudo-Jaffe Ellipsoid (PJE) lens with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"PJELens/#LensFactory.Lenses.PJELens.potential!","page":"PJE Lens","title":"LensFactory.Lenses.PJELens.potential!","text":"potential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, θt::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, θt::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\n","category":"function"},{"location":"PJELens/#LensFactory.Lenses.PJELens.deflection!","page":"PJE Lens","title":"LensFactory.Lenses.PJELens.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, θt::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, θt::RV, ϵ::RV, pa::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"PJELens/#LensFactory.Lenses.PJELens.jacobian!","page":"PJE Lens","title":"LensFactory.Lenses.PJELens.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, θt::RV, ϵ::RV, pa::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, θxc::RV, θyc::RV, vd::RV, θs::RV, θt::RV, ϵ::RV, pa::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"#LensFactory.jl","page":"Home","title":"LensFactory.jl","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"(Image: Build status (Github Actions)) (Image: codecov.io) (Image: arXiv aaaa.bbbbb)","category":"page"},{"location":"","page":"Home","title":"Home","text":"","category":"page"},{"location":"#Introduction","page":"Home","title":"Introduction","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"LensFactory is a gravitational lensing package fully developed in julia. At present it has support  for basic lensing and as we go along it is expected to have more features.","category":"page"},{"location":"","page":"Home","title":"Home","text":"","category":"page"},{"location":"#Installation","page":"Home","title":"Installation","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"To install, activate pkg mode by pressing ] in julia REPL and then type: ","category":"page"},{"location":"","page":"Home","title":"Home","text":"pkg> add \"https://github.com/akmeena766/LensFactory.jl\"","category":"page"},{"location":"","page":"Home","title":"Home","text":"To use the LensFactory package in your current julia session, type: ","category":"page"},{"location":"","page":"Home","title":"Home","text":"julia> using LensFactory","category":"page"},{"location":"","page":"Home","title":"Home","text":"","category":"page"},{"location":"#Examples","page":"Home","title":"Examples","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"To understand the use of various modules and functtions in LensFactory, readers are encouraged to go through the examples here: LensFactory_Examples.","category":"page"},{"location":"","page":"Home","title":"Home","text":"note: Note\nPlease keep in mind that LensFactory is in heavy developement and examples are based on the  current dev version. If any of the examples are not working, please let me know.","category":"page"},{"location":"","page":"Home","title":"Home","text":"","category":"page"},{"location":"#Feedback","page":"Home","title":"Feedback","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"I would be very happy to receive any suggestions, comments, or questions regarding LensFactory. Please feel free to drop an email to: ashishmeena766@gmail.com ","category":"page"},{"location":"","page":"Home","title":"Home","text":"","category":"page"},{"location":"#Citation","page":"Home","title":"Citation","text":"","category":"section"},{"location":"ExternalEffects/#LensFactory.Lenses.init_ExternalEffects","page":"External Effects","title":"LensFactory.Lenses.init_ExternalEffects","text":"init_ExternalEffects(kappa::RV=NaN, gamma1::RV=NaN, gamma2::RV=NaN)\n\nInitialize constant external effects with the given parameters.\n\n\n\n\n\n","category":"type"},{"location":"ExternalEffects/#LensFactory.Lenses.ExternalEffects.potential!","page":"External Effects","title":"LensFactory.Lenses.ExternalEffects.potential!","text":"potential!(ψ::T, θx::T, θy::T, kv::RV, g1::RV, g2::RV) where T <: RV\n\n\n\n\n\npotential!(ψ::T, θx::T, θy::T, kv::RV, g1::RV, g2::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"ExternalEffects/#LensFactory.Lenses.ExternalEffects.deflection!","page":"External Effects","title":"LensFactory.Lenses.ExternalEffects.deflection!","text":"deflection!(ψx::T, ψy::T, θx::T, θy::T, kv::RV, g1::RV, g2::RV) where T <: RV\n\n\n\n\n\ndeflection!(ψx::T, ψy::T, θx::T, θy::T, kv::RV, g1::RV, g2::RV) where T <: ROA\n\n\n\n\n\n","category":"function"},{"location":"ExternalEffects/#LensFactory.Lenses.ExternalEffects.jacobian!","page":"External Effects","title":"LensFactory.Lenses.ExternalEffects.jacobian!","text":"jacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, kv::RV, g1::RV, g2::RV) where T <: RV\n\n\n\n\n\njacobian!(ψxx::T, ψyy::T, ψxy::T, θx::T, θy::T, kv::RV, g1::RV, g2::RV) where T <: ROA\n\n\n\n\n\n","category":"function"}]
